use vstd::prelude::*;

verus! {

/// Returns the length `l` of the longest common prefix of `a` and `b`.
/// Ensures:
/// 1) `l <= a.len()`
/// 2) `l <= b.len()`
/// 3) The first `l` elements of `a` and `b` are equal: `a@[..l] == b@[..l]`
/// 4) If `l` is strictly less than the length of both arrays, then
///    the next elements differ: `(l < a.len() && l < b.len()) ==> a@[l] != b@[l]`
fn longest_prefix(a: &[i32], b: &[i32]) -> (l: usize)
    ensures
        l <= a.len(),
        l <= b.len(),
        a@[..l] == b@[..l],
        (l < a.len() && l < b.len()) ==> a@[l] != b@[l],
{
    // We only need to scan up to the shorter of the two slices.
    let n = if a.len() < b.len() { a.len() } else { b.len() };

    let mut i: usize = 0;
    // Invariant:
    //   1) 0 <= i <= n,
    //   2) the first i elements agree: a@[..i] == b@[..i]
    // Decreases: n - i, to ensure termination.
    while i < n && a[i] == b[i]
        invariant
            i <= n,
            a@[..i] == b@[..i],
        decreases n - i,
    {
        i = i + 1;
    }

    // Now either i == n, or a[i] != b[i].
    i
}

} // end of verus! block

fn main() {
    // Example usages (outside of Verus verification):
    let a: Vec<i32> = vec![1, 2, 3, 4];
    let b: Vec<i32> = vec![1, 2, 5];
    let l = longest_prefix(&a, &b);
    assert!(l == 2);

    let c: Vec<i32> = vec![7, 8];
    let d: Vec<i32> = vec![7, 8, 9];
    let m = longest_prefix(&c, &d);
    assert!(m == 2);

    let e: Vec<i32> = vec![];
    let f: Vec<i32> = vec![1, 2];
    let n = longest_prefix(&e, &f);
    assert!(n == 0);
}